    INSERT INTO public.mcqs (topic_id, question, options, correct_index, explanation, "order")
    VALUES 
    (v_topic_id, 'GnRH is secreted by the:', '["Anterior pituitary", "Posterior pituitary", "Hypothalamus", "Gonads", "Adrenal cortex"]', 2, 'Gonadotropin-releasing hormone is synthesized in the hypothalamus.', 1),
    (v_topic_id, 'GnRH stimulates the anterior pituitary to release:', '["ACTH and TSH", "FSH and LH", "ADH and oxytocin", "Prolactin and GH only", "Estrogen and progesterone"]', 1, 'FSH and LH are the gonadotropins.', 2),
    (v_topic_id, 'GnRH is physiologically most effective when secreted in a:', '["Continuous pattern", "Pulsatile pattern", "Once-monthly burst only", "Stress-dependent pattern only", "Meal-dependent pattern only"]', 1, 'Pulsatility prevents pituitary desensitization.', 3),
    (v_topic_id, 'Continuous administration of GnRH would most likely:', '["Increase FSH and LH indefinitely", "Suppress gonadotropin secretion after initial stimulation", "Increase testosterone directly without pituitary input", "Increase prolactin secretion only", "Increase oxytocin release only"]', 1, 'Downregulation of receptors occurs with continuous exposure.', 4),
    (v_topic_id, 'LH in males primarily stimulates:', '["Sertoli cells", "Leydig cells", "Seminal vesicles", "Prostate gland", "Epididymis"]', 1, 'LH targets Leydig cells for androgen production.', 5),
    (v_topic_id, 'Leydig cells mainly produce:', '["Inhibin B", "Testosterone", "Progesterone", "FSH", "Estrogen only"]', 1, 'Testosterone is the primary product of Leydig cells.', 6),
    (v_topic_id, 'FSH in males primarily stimulates:', '["Leydig cells", "Sertoli cells", "Prostate gland", "Vas deferens", "Epididymal smooth muscle"]', 1, 'FSH supports spermatogenesis via the Sertoli cells.', 7),
    (v_topic_id, 'Sertoli cells produce which hormone that feeds back mainly on FSH?', '["Testosterone", "Progesterone", "Inhibin B", "hCG", "Oxytocin"]', 2, 'Inhibin B provides specific negative feedback for FSH.', 8),
    (v_topic_id, 'The blood-testis barrier is formed mainly by:', '["Leydig cells", "Sertoli cell tight junctions", "Peritubular smooth muscle", "Epididymal epithelium", "Endothelial cells only"]', 1, 'Tight junctions between Sertoli cells create a privileged environment.', 9),
    (v_topic_id, 'A major function of the blood-testis barrier is to:', '["Increase urinary testosterone", "Protect developing germ cells from immune exposure", "Trigger ejaculation", "Stimulate LH release", "Activate sperm motility"]', 1, 'Protects haploid cells (which appear "foreign") from the immune system.', 10),
    (v_topic_id, 'Spermatogenesis occurs in the:', '["Epididymis", "Seminiferous tubules", "Vas deferens", "Prostate", "Ejaculatory ducts"]', 1, 'The germinal epithelium of the tubules is the site of production.', 11),
    (v_topic_id, 'Sperm acquire motility mainly in the:', '["Seminiferous tubules", "Epididymis", "Vas deferens", "Seminal vesicles", "Prostate"]', 1, 'Sperm mature as they travel through the epididymal duct.', 12),
    (v_topic_id, 'Seminal vesicles contribute semen that is characteristically:', '["Acidic and enzyme-rich", "Alkaline and fructose-rich", "Purely watery with no nutrients", "Rich in testosterone", "Rich in bile salts"]', 1, 'Fructose is the fuel source for sperm motility.', 13),
    (v_topic_id, 'The prostate contributes semen that contains:', '["Fructose only", "Citrate and proteolytic enzymes", "Spermatozoa only", "hCG only", "Progesterone only"]', 1, 'Prostatic fluid includes PSA (Prostate Specific Antigen).', 14),
    (v_topic_id, 'Bulbourethral glands primarily secrete:', '["Acidic fluid", "Mucus for lubrication", "Fructose-rich fluid", "Testosterone", "Sperm cells"]', 1, 'Provides lubrication and neutralizes the acidic urethra.', 15),
    (v_topic_id, 'Penile erection is mediated primarily by:', '["Sympathetic stimulation", "Parasympathetic-mediated vasodilation", "Somatic motor output only", "Adrenal cortisol secretion", "Pituitary gonadotropins"]', 1, 'Parasympathetic nerves release NO for vasodilation.', 16),
    (v_topic_id, 'A key mediator of penile erection is:', '["Histamine", "Nitric oxide", "Aldosterone", "ADH", "Prolactin"]', 1, 'NO increases cGMP levels in the corpora cavernosa.', 17),
    (v_topic_id, 'Ejaculation is mediated primarily by:', '["Parasympathetic outflow", "Sympathetic outflow", "Vagal stimulation only", "FSH release", "Oxytocin only"]', 1, 'Sympathetic reflex causes emission and ejaculation.', 18),
    (v_topic_id, 'The external urethral sphincter is controlled by:', '["Only autonomic fibers", "Somatic motor innervation", "Only parasympathetic fibers", "Only sympathetic fibers", "Hormones only"]', 1, 'The pudendal nerve provides voluntary (somatic) control.', 19),
    (v_topic_id, 'In the normal ovarian cycle, ovulation is triggered by the mid-cycle surge of:', '["FSH", "LH", "Prolactin", "Progesterone", "hCG"]', 1, 'High estrogen switches to positive feedback, causing the LH surge.', 20),
    (v_topic_id, 'The first half of the ovarian cycle is the:', '["Luteal phase", "Follicular phase", "Secretory phase", "Menstrual phase", "Implantation phase"]', 1, 'Dominated by follicle growth under FSH/LH.', 21),
    (v_topic_id, 'After ovulation, the ruptured follicle becomes the:', '["Corpus albicans", "Corpus luteum", "Zona pellucida", "Decidua", "Endometrium"]', 1, 'The luteal cells produce progesterone.', 22),
    (v_topic_id, 'Granulosa cells are primarily stimulated by:', '["LH", "FSH", "ACTH", "TSH", "Oxytocin"]', 1, 'FSH acts on granulosa cells similarly to Sertoli cells in males.', 23),
    (v_topic_id, 'Theca interna cells are primarily stimulated by:', '["FSH", "LH", "Prolactin", "Inhibin", "Estrogen only"]', 1, 'LH acts on theca cells similarly to Leydig cells in males.', 24),
