    (v_topic_id, 'During the follicular phase, the dominant ovarian estrogen is:', '["Estriol", "Estradiol", "Progesterone", "Testosterone", "hCG"]', 1, 'E2 (17-beta estradiol) is the primary estrogen of reproductive years.', 26),
    (v_topic_id, 'Estrogen stimulates:', '["Secretory transformation of endometrium", "Proliferation of endometrium", "Menstrual shedding directly", "Thick cervical mucus", "Reduced uterine growth"]', 1, 'Builds up the functional layer of the endometrium.', 27),
    (v_topic_id, 'Sustained high estrogen levels in mid-cycle produce:', '["Negative feedback only", "Positive feedback causing LH surge", "Immediate menstruation", "Suppression of ovulation", "Reduced GnRH pulse activity only"]', 1, 'The mechanism that triggers the LH surge.', 28),
    (v_topic_id, 'Progesterone is secreted mainly by the:', '["Theca externa", "Corpus luteum", "Anterior pituitary", "Hypothalamus", "Adrenal medulla only"]', 1, 'Secreted in large amounts during the luteal phase.', 29),
    (v_topic_id, 'Progesterone converts the endometrium into the:', '["Proliferative phase", "Secretory phase", "Menstrual phase", "Atrophic phase", "Basal phase"]', 1, 'Prepares the uterus for possible implantation.', 30),
