-- ==========================================
-- Reproductive Physiology MCQs Migration
-- 100 Questions | Semester 2 First Year
-- ==========================================

DO $$
DECLARE
    v_topic_id UUID;
BEGIN
    -- 1. Get Topic ID
    SELECT id INTO v_topic_id FROM public.topics 
    WHERE title = 'Reproductive Physiology' AND (semester_id = 2 OR usmle_step = 1) 
    LIMIT 1;

    IF v_topic_id IS NULL THEN
        RAISE EXCEPTION 'Topic "Reproductive Physiology" not found.';
    END IF;

    -- 2. Clear existing standalone MCQs for this topic
    DELETE FROM public.mcqs WHERE topic_id = v_topic_id;

    -- 3. Insert 100 MCQs

    RAISE NOTICE 'Reproductive Physiology 100 MCQs populated successfully.';
END $$;
